getBookingPaymentStatus() {
  if (this.scheduling?.type === 'BLOCK' || this.scheduling?.status === 'BLOCKED') return 'blocked'

  const users = this.scheduling?.users || []
  const transactions = this.scheduling?.transactions || users.map((user: any) => user.transaction).filter(Boolean)
  const completedPayments = transactions.filter((transaction: any) => transaction?.status === 'COMPLETED').length
  const expectedPayments = this.scheduling?.users_ids_count || users.length || 1
  const paidAmount = Number(this.scheduling?.balance?.paid || 0)
  const dueAmount = Number(this.scheduling?.balance?.due || 0)

  if (completedPayments >= expectedPayments || this.scheduling?.transaction?.status === 'COMPLETED' || (paidAmount > 0 && dueAmount <= 0)) return 'total'
  if (completedPayments > 0 || paidAmount > 0) return 'partial'
  return 'none'
},

